    // `EditorViewController+Export.swift`.

    // MARK: - Track commands

    /// ⇧⌘N — a new track at the front, which is the top lane.
    func newTrackCommand() {
        guard let document = document else { return }
        document.applyEdit(
            "New Track", .addTrack(index: document.editedProject.snapshot.tracks.count))
    }

    /// A non-empty track refuses to go without `with_clips`, so the clips it
    /// would take go in the question rather than in a beep. `id` is the
    /// track context menu's clicked track; Track ▸ Remove Track passes none
    /// and acts on `currentTrack`.
    func removeTrackCommand(_ id: UInt32? = nil) {
        let track: TrackSnapshot?
        if let id = id {
            track = document?.editedProject.snapshot.track(id)
        } else {
            track = currentTrack
        }
        guard let document = document, let track = track else {
            NSSound.beep()
            return
        }
        let clips = document.editedProject.snapshot.clips(onTrack: track.id)
        guard !clips.isEmpty else {
            document.applyEdit("Remove Track", .removeTrack(track: track.id))
            return
        }
        guard let window = view.window else {
            NSSound.beep()
            return
        }
        let alert = NSAlert()
        alert.messageText = "Remove “\(track.name)”?"
        alert.informativeText =
            clips.count == 1
            ? "The track still holds 1 clip, which will be removed with it."
            : "The track still holds \(clips.count) clips, which will be removed with it."
        alert.addButton(withTitle: "Remove")
        alert.addButton(withTitle: "Cancel")
        alert.beginSheetModal(for: window) { [weak document] response in
            guard response == .alertFirstButtonReturn, let document = document else { return }
            // A sheet's completion is not an AppKit event: the grouped entry
            // point is mandatory here (app/CLAUDE.md's undo pitfall).
            document.performGroupedEdit(
                "Remove Track", [.removeTrack(track: track.id, withClips: true)])
        }
    }

    func removeEmptyTracksCommand() {
        document?.applyEdit("Remove Empty Tracks", .removeEmptyTracks())
    }

    /// Track ▸ Hide Video / Mute Audio / Lock Track / Solo — the same four
    /// toggles the header column draws. Solo is audio only and mute wins over
    /// it (spec §7.2); the core's envelopes apply the rule, so this is one
    /// flag like the other three. The fifth switch, `.mix`, opens the current
    /// track's Volume and Pan popover (spec §11 AU-105).
    func toggleTrack(_ button: TimelineHeaderButton) {
        guard let document = document, let track = currentTrack else {
            NSSound.beep()
            return
        }
        switch button {
        case .hidden:
            document.applyEdit("Hide Track", .setTrack(track: track.id, hidden: !track.hidden))
        case .muted:
            document.applyEdit("Mute Track", .setTrack(track: track.id, muted: !track.muted))
        case .locked:
            document.applyEdit("Lock Track", .setTrack(track: track.id, locked: !track.locked))
        case .solo:
            document.applyEdit("Solo Track", .setTrack(track: track.id, solo: !track.solo))
        case .mix:
            timeline?.showTrackMix(track)
        }
    }

    // MARK: - Markers
    static func button(at local: CGPoint, height: CGFloat) -> TimelineHeaderButton? {
        let buttons: [TimelineHeaderButton] = [.hidden, .muted, .locked, .solo, .mix]
        for (index, button) in buttons.enumerated()
        where buttonRect(index, height: height).insetBy(dx: -1, dy: -1).contains(local) {
            return button
        }
        return nil
    }

    override func draw(_ dirtyRect: NSRect) {
        guard let owner = timeline else { return }
        let layout = owner.layout
        DS.chromeBackground.setFill()
        bounds.fill()

        for (index, track) in owner.snapshot.tracks.enumerated() {
            let row = layout.row(forTrackIndex: index)
            // Local y: the column's frame starts at the ruler's height.
            let top = layout.rowTop(row) - TimelineLayout.rulerHeight
            let height = layout.trackHeight(row: row)
            let rect = CGRect(x: 0, y: top, width: bounds.width, height: height)
            guard rect.intersects(dirtyRect) else { continue }
            DS.chromeBackground.setFill()
            rect.fill()
            DS.border.setFill()
            NSRect(x: 0, y: rect.maxY, width: bounds.width, height: 1).fill()

            TimelineDraw.label(
                track.name.isEmpty ? "Track \(index + 1)" : track.name,
                in: CGRect(
                    x: 8, y: rect.minY + 2,
                    width: bounds.width - 14 - matteTagWidth(track, rowHeight: height), height: 13),
                font: DS.sans(11, weight: .semibold), color: DS.textStrong)
            drawMatteTag(track, row: rect, tracks: owner.snapshot.tracks)

            let toggles: [(TimelineHeaderButton, String, String, Bool)] = [
                (.hidden, track.hidden ? "eye.slash" : "eye", "H", track.hidden),
                (.muted, track.muted ? "speaker.slash" : "speaker.wave.2", "M", track.muted),
                (.locked, track.locked ? "lock" : "lock.open", "L", track.locked),
                (.solo, "headphones", "S", track.solo),
                (.mix, "slider.horizontal.3", "V", track.mixIsSet),
            ]
            for (position, toggle) in toggles.enumerated() {
                var box = Self.buttonRect(position, height: height)
                box.origin.y += rect.minY
                if toggle.3 {
                    DS.selectionFill.setFill()
                    box.fill()
                }
                TimelineDraw.symbol(
                    toggle.1, fallback: toggle.2, in: box,
                    tint: toggle.3 ? DS.accent : DS.textMuted)
            }
        }

        // The drop line for a header reorder in flight.
        if let drag = timeline?.trackDrag, drag.didMove, drag.row != drag.originalRow {
            DS.playhead.setFill()
            let y = layout.rowTop(drag.row) - TimelineLayout.rulerHeight
            NSRect(x: 0, y: y - 1, width: bounds.width, height: 2).fill()
        }

        DS.border.setFill()
        NSRect(x: bounds.width - 1, y: 0, width: 1, height: bounds.height).fill()
    }
}

