/// Compares what the drag asked for with what the core did. `onLiveEnd`
/// has already published, so `snapshot` is the answer.
private func checkRefusal(of session: ClipDragSession) {
    // A drop that asked for a new track lands on a row that did not exist
    // when the drag started, so there is nothing to compare — and a drop
    // that duplicated moved the copies, not the anchor.
    guard session.didMove, !session.duplicating, !session.needsNewTrack,
          let clip = snapshot.clip(session.anchor),
          let index = snapshot.trackIndex(of: clip.track)
    else { return }
    let landedRow = layout.row(forTrackIndex: index)
    guard clip.start != session.proposedStart || landedRow != session.row else { return }
    let row = min(max(session.row, 0), max(layout.trackCount - 1, 0))
    // Both ends of the springback are the clip's BODY, not its lane rect:
    // the redesign insets a bar 3 pt top and bottom
    // (`TimelineContentView.bodyRect`), so a ghost built from the lane
    // would be a taller rectangle than the clip it claims to be — and it
    // is drawn on the clip's own corner radius, over the clip, where the
    // difference is the whole point of the animation.
    var ghost = TimelineContentView.bodyRect(layout.clipRect(clip, row: row))
    ghost.origin.x = layout.x(for: session.proposedStart)
    flashRefusal(
        from: ghost,
        to: TimelineContentView.bodyRect(layout.clipRect(clip, row: landedRow)))
}

private func beginClipDrag(anchor: UInt32, at point: CGPoint, flags: NSEvent.ModifierFlags) {
    guard let clip = snapshot.clip(anchor),
          let index = snapshot.trackIndex(of: clip.track),
          !snapshot.tracks[index].locked
    else { return }
    let ids = selection.contains(anchor) ? Array(selection) : [anchor]
    let dragged = snapshot.clips.filter { ids.contains($0.id) }
    guard !dragged.isEmpty else { return }
    let duplicating = flags.contains(.option)

    // Every id the ops will need, probed against the handle the gesture
    // is about to snapshot — the ONE moment the current project and the
    // live-edit base are the same thing.
    let existingClips = Set(snapshot.clips.map { $0.id })
    let existingTracks = Set(snapshot.tracks.map { $0.id })
    var copies: [UInt32] = []
    var copyShift: Ticks = 0
    var prefix: [ReelOp] = []
    if duplicating {
        let probed = onProbe?([.duplicate(clips: ids)])
        let made = (probed?.clips ?? []).filter { !existingClips.contains($0.id) }
            .sorted { $0.start < $1.start }
        if !made.isEmpty {
            copies = made.map { $0.id }
            let from = dragged.map { $0.start }.min() ?? 0
            copyShift = (made.map { $0.start }.min() ?? from) - from
            prefix = [.duplicate(clips: ids)]
        }
    }
    let count = snapshot.tracks.count
    let top = probeTrack(prefix + [.addTrack(index: count)], existing: existingTracks)
    let bottom = probeTrack(prefix + [.addTrack(index: 0)], existing: existingTracks)

    dragBase = snapshot
    dragHeights = TimelineLayout.trackHeights(
        for: snapshot, sizeIndex: trackHeightIndex)
    dragRowHeights = layout.rowHeights
    dragSnapper = makeSnapper(excluding: ids, suppressed: flags.contains(.command))
    clipDrag = ClipDragSession(
        clips: ids, anchor: anchor, anchorStart: clip.start,
        anchorRow: layout.row(forTrackIndex: index),
        grabTime: layout.time(atX: point.x),
        spanStart: dragged.map { $0.start }.min() ?? clip.start,
        trackCount: count, duplicating: !copies.isEmpty, copies: copies, copyShift: copyShift,
        newTrackTop: top, newTrackBottom: bottom,
        row: layout.row(forTrackIndex: index))
    onLiveBegin?()
}

private func probeTrack(_ ops: [ReelOp], existing: Set<UInt32>) -> UInt32? {
    guard let probed = onProbe?(ops) else { return nil }
    return probed.tracks.first { !existing.contains($0.id) }?.id
}

private func beginTrim(_ id: UInt32, edge: TimelineEdge, flags: NSEvent.ModifierFlags) {
    guard let clip = snapshot.clip(id),
          let index = snapshot.trackIndex(of: clip.track),
          !snapshot.tracks[index].locked
    else { return }
    let frame = max(snapshot.canvas.fps.frameDuration, 1)
    dragSnapper = makeSnapper(excluding: [id], suppressed: flags.contains(.command))
    trim = TrimSession(
        clip: id, edge: edge,
        stretch: flags.contains(.option) && clip.source.hasSourceBound,
        alone: clip.isLinkedSound,
        originalStart: clip.start, originalEnd: clip.end, frame: frame,
        time: edge == .start ? clip.start : clip.end)
    onLiveBegin?()
}

/// The destination track id for the row a drag is over, or nil to leave
/// every clip on its own track. Read from the gesture's base handle.
private func destination(for session: ClipDragSession) -> UInt32? {
    guard let base = dragBase, session.row != session.anchorRow,
          (0..<base.tracks.count).contains(session.row)
    else { return nil }
    return base.tracks[base.tracks.count - 1 - session.row].id
}

/// ⌥-click a track header: every clip on it (spec §9). Here rather than
/// in `EditorViewController+Edge.swift` only because `selection` is
/// `private(set)` — it is the same view-state channel `selectClip` and
/// the marquee use, and registers no undo step.
private func selectClipsOnTrack(_ track: UInt32) {
    let ids = Set(snapshot.clips.filter { $0.track == track }.map { $0.id })
    guard selection != ids else { return }
    selection = ids
    onSelectionChanged?(selection)
}

/// A press on empty timeline space — a lane's gap, or above or below
/// the lanes: a bare press clears the selection and ⇧ keeps it, then the
/// band starts (`RangeSession`). One body for `.lane` and `.outside`, so
/// the two places a band can start cannot drift apart. The clear is
/// posted at the press rather than at the first drag, which is what
/// makes a bare CLICK on empty space deselect.
private func beginMarquee(at point: CGPoint, flags: NSEvent.ModifierFlags) {
    if !flags.contains(.shift), !selection.isEmpty {
        selection = []
        onSelectionChanged?(selection)
    }
    marquee = RangeSession(
        origin: point, additive: flags.contains(.shift), base: selection, current: point)
}

private func selectClip(_ id: UInt32, flags: NSEvent.ModifierFlags) {
    if flags.contains(.shift) {
        if selection.contains(id) {
            selection.remove(id)
        } else {
            selection.insert(id)
        }
    } else if !selection.contains(id) {
        selection = [id]
    }
    onSelectionChanged?(selection)
}

private func toggleHeader(_ button: TimelineHeaderButton, row: Int) {
    guard let track = track(atRow: row) else { return }
    toggle(button, on: track)
}

private func renameTrack(_ track: TrackSnapshot, row: Int) {
    beginRename(
        in: headers, frame: trackRenameFrame(row: row), text: track.name,
        relocate: trackRenameRelocator(track.id)
    ) { [weak self] name in
        self?.onGroupedEdit?("Rename Track", [.setTrack(track: track.id, name: name)])
    }
}

private func renameMarker(_ marker: MarkerSnapshot) {
    beginRename(
        in: ruler, frame: markerRenameFrame(marker), text: marker.name,
        relocate: markerRenameRelocator(marker.id)
    ) { [weak self] name in
        self?.onGroupedEdit?("Rename Marker", [.setMarker(marker: marker.id, name: name)])
    }
}

// MARK: - Shared lookups (the drawing views use these too)

func track(atRow row: Int) -> TrackSnapshot? {
    let index = layout.trackIndex(forRow: row)
    return snapshot.tracks.indices.contains(index) ? snapshot.tracks[index] : nil
}

/// True when the clip contributes samples, i.e. deserves a waveform and
/// fade handles. A nest clip has no media but does have a mix — the core
/// gives it audio props exactly when something inside it sings, and its
/// fades apply to all of that (`core/src/audio.rs`) — so it gets the
/// handles. There is no waveform to draw for one; `drawWaveform` finds no
/// media and returns.
func hasAudio(_ clip: ClipSnapshot) -> Bool {
    guard clip.enabled.audio else { return false }
    if case .nest = clip.source { return clip.audio != nil }
    guard let media = snapshot.media(for: clip) else { return false }
    return media.hasAudio
}

/// True when the clip contributes pixels — a filmstrip goes here.
func hasVideo(_ clip: ClipSnapshot) -> Bool {
    guard clip.enabled.video else { return false }
    switch clip.source {
    case .media, .still, .image: return snapshot.media(for: clip)?.hasVideo ?? false
    case .text, .shape, .graphic, .nest, .adjustment: return false
    }
}

/// Source time under a timeline time, for the filmstrip and the waveform.
/// Source advances at `speed` per timeline tick (spec §6 `set_speed`).
///
/// **Mirrored when the clip plays backwards** (`ReverseMirror`, spec §11
/// D4-6): the caches both callers index are the FORWARD file's, while `in`
/// and this offset are measured in the stream the clip PLAYS. It is inside

/// ⌥ duplicates. `duplicate` mints its copies inside the core, so the ids to
/// move are learned once at mouse-down by applying `duplicate` to the
/// current handle PURELY (`TimelineView.onProbe`) — a question, not an edit.
struct ClipDragSession {
    /// Every dragged clip, the anchor first is not required — `anchor` names
    /// it explicitly.
    let clips: [UInt32]
    let anchor: UInt32
    let anchorStart: Ticks
    let anchorRow: Int
    /// Time under the pointer at mouse-down, so the bar does not jump to
    /// centre itself on the cursor.
    let grabTime: Ticks
    /// Earliest start in the dragged set: the group's own origin, which is
    /// what snapping tests against a candidate.
    let spanStart: Ticks
    let trackCount: Int
    let duplicating: Bool
    /// Ids `duplicate` will mint, in the same order as `clips` sorted by
    /// start; empty when the probe failed and the drag falls back to a move.
    let copies: [UInt32]
    /// How far `duplicate` pushed the copies past the originals, so the move
    /// that follows lands them under the pointer and not past the span.
    let copyShift: Ticks
    /// Ids `add_track` will mint for a drop above the top lane / below the
    /// bottom one, probed with the same op PREFIX the drop will use so the
    /// core mints them in the same order. nil disables that end.
    let newTrackTop: UInt32?
    let newTrackBottom: UInt32?

    var delta: Ticks = 0
    var row: Int
    /// Non-nil while the drag is locked to a snap candidate.
    var guide: Ticks?
    /// False until the pointer actually leaves the press point — a click
    /// that merely selects must not register an undo step.
    var didMove = false

    /// True when the drop is past either end of the stack, which spec §4.4
    /// turns into a new track rather than a refusal.
    var needsNewTrack: Bool { row < 0 || row >= trackCount }

    /// Where `add_track` inserts it: model index `trackCount` (the front) for
    /// a drop above the top lane, 0 (the back) for one below the bottom.
    var newTrackIndex: Int { row < 0 ? trackCount : 0 }

    /// The anchor's proposed start — what the refusal check compares against
    /// once the core has had its say.
    var proposedStart: Ticks { anchorStart + delta }

    /// The ops for the current drag state, as ONE undo step.
    ///
    /// Order matters and is the order the probes assumed: `duplicate` first
    /// (so its copies take the low ids), then `add_track`, then the move.
    /// `destination` is the id of an EXISTING track to land on, or nil to
    /// leave every clip where it is vertically.
    func ops(destination: UInt32?) -> [ReelOp] {
        var ops: [ReelOp] = []
        let moved = duplicating && !copies.isEmpty ? copies : clips
        let shift = duplicating && !copies.isEmpty ? delta - copyShift : delta
        if duplicating, !copies.isEmpty {
            ops.append(.duplicate(clips: clips))
        }
        var target = destination
        if needsNewTrack, let created = row < 0 ? newTrackTop : newTrackBottom {
            ops.append(.addTrack(index: newTrackIndex))
            target = created
        }
        ops.append(.moveClip(clips: moved, delta: shift, track: target))
        return ops
    }

    /// Advances the drag. `time` is the time under the pointer and `row` the
    /// lane under it; snapping is applied to the GROUP's start so the whole
    /// selection clicks into place together.
    mutating func update(time: Ticks, row: Int, snapper: TimelineSnapper) {
        let raw = time - grabTime
        let resolved = snapper.resolve(spanStart + raw)
        delta = resolved.time - spanStart
        guide = resolved.guide
        // A clip can never start before zero (§6 clamps it); keeping the
        // preview honest about that stops the group sliding while the core
        // refuses to follow.
        if spanStart + delta < 0 { delta = -spanStart }
        self.row = row
        didMove = true
    }
}

// MARK: - Trim

/// Dragging a clip edge (spec §6 `trim_start` / `trim_end`), or with ⌥ a
/// rate stretch of the end.
///
/// **Pitfall:** `rate_stretch` only takes `to_end`, so ⌥ on the START edge
/// has nothing to express — it trims like a bare drag rather than pretending
/// to stretch and silently doing something else.
struct TrimSession {
    let clip: UInt32
    let edge: TimelineEdge
    let stretch: Bool
    /// The grabbed clip is a linked SOUND half, so its edge moves without
    /// its picture's — the J- or L-cut (spec §11 AU-93). A picture's edge
    /// carries to a sound whose edge coincides.
    let alone: Bool
    let originalStart: Ticks
    let originalEnd: Ticks
    /// One frame of the document's grid: the minimum a clip may keep.
    let frame: Ticks

    var time: Ticks
    var guide: Ticks?
    var didMove = false

    /// True when ⌥ actually changes the op.
    var isRateStretch: Bool { stretch && edge == .end }

    var op: ReelOp {
        switch edge {
        case .start:
            return .trimStart(clip: clip, to: min(time, originalEnd - frame), alone: alone)
// MARK: - Fade handles

/// The small squares at the audio corners, dragged inward to set
/// `audio.fade_in` / `audio.fade_out` (spec §4.4). The length is a duration,
/// not a time, so it never snaps to a clip edge — it clamps to the clip.
struct FadeHandleSession {
    let clip: UInt32
    let edge: TimelineEdge
    let clipStart: Ticks
    let clipEnd: Ticks
    var length: Ticks
    var didMove = false

    var op: ReelOp {
        var patch = AudioPatch()
        switch edge {
        case .start: patch.fadeIn = length
        case .end: patch.fadeOut = length
        }
        return .setAudio(clips: [clip], patch: patch)
    }

    /// `time` is the pointer's time; the fade is the distance from the
    /// matching edge, capped at the clip's own length.
    mutating func update(time: Ticks, fps: Fps) {
        let span = max(clipEnd - clipStart, 0)
        let raw: Ticks
        switch edge {
        case .start: raw = time - clipStart
        case .end: raw = clipEnd - time
        }
        length = ReelTime.snapToFrame(max(0, min(raw, span)), fps: fps)
        didMove = true
    }
}

// MARK: - Track reorder

/// Dragging a track header to restack it (spec §4.4). The drag is in display
/// rows (0 = top = front-most); `op` converts back to the model's index,
/// where 0 is the BACK of the stack.
struct TrackDragSession {
    let track: UInt32
    let originalRow: Int
    let trackCount: Int
    var row: Int
    var didMove = false

    var op: ReelOp? {
        guard row != originalRow, (0..<trackCount).contains(row) else { return nil }
        return .moveTrack(track: track, index: trackCount - 1 - row)
    }

    mutating func update(row: Int) {
        self.row = min(max(row, 0), max(trackCount - 1, 0))
        didMove = true
    }
}

extension ClipSnapshot {
    /// A linked SOUND half — Detach Audio's sound, its picture off — whose
    /// edge a trim or roll moves alone (spec §11 AU-93): the half you grab
    /// decides.
    var isLinkedSound: Bool { linked != nil && !enabled.video }
}

import AppKit

/// The inline clip rename — a double-click on a clip, or Clip ▸ Rename…
/// (⇧⌘R) — over the one editor `TimelineView` already keeps for a track
/// header and a marker (`beginRename`).
///
/// It is an extension because `TimelineView.swift` is frozen at wiring
/// (app/CLAUDE.md). The frozen file keeps two hooks: the `clicks == 2` branch
/// of `beginGesture`'s `.clip` case, placed BEFORE `selectClip` for the reason
/// the ⌥⇧ slip branch is (⇧ would otherwise be read as "toggle membership"),
/// and `relocateRename()` at the end of `rebuildLayout`, which moves the open
/// field to the NEW layout's rect through the `relocate` closure given here.
/// So the field survives a zoom, a resize and any document change while its
/// clip exists — an agent's edit, a save's clean/dirty crossing, another
/// track's solo — instead of being ended, which would COMMIT whatever was
/// typed so far (removing the field ends its editing), and under an agent's
/// grouped edit would fold that half-typed rename into the agent's undo step.
/// When the clip is GONE (a delete under the open field, from ⌘⌫, the
/// timeline bar or an MCP `delete_clips`) the relocator answers nil and the
/// frozen file ends the field with its commit dropped, so no `set_clip` is
/// sent to a dead id — which the core would refuse, and the document would
/// put in a sheet after a delete that succeeded.
///
/// The field sits over the clip's name strip in `content` coordinates — the
/// space `TimelineLayout.clipRect` answers in, so there is nothing to
/// convert — clamped to the visible lanes (`clipRenameFrame`), and it opens
/// showing the name the strip shows (`ProjectSnapshot.name(of:)`), own name
/// or fallback, because what you double-clicked is what you expect to be
/// editing. What it COMMITS is the clip's own name: one `set_clip`, whose
/// core trims the text. Two commits are dropped by the shared editor itself:
///
/// * **An unchanged one.** The field opened on the fallback; sending that
///   back would pin it as the clip's OWN name — an undo step and a dirty
///   document for nothing, and a text clip's strip frozen at the words it
///   had. Return, Tab and a click elsewhere commit, and Escape closes the
///   field with its commit dropped (`control(_:textView:doCommandBy:)`), so
///   an accidental double-click has a harmless way out by every exit.
/// * **An empty one** — right for a track and a marker, whose names cannot
///   be cleared. So the strip cannot clear a name back to the fallback. That
///   is the Clip tab's job: the header field in `ClipSelectionHeaderView`
///   (`ClipPane.swift`) sends `null` for an emptied field.
///
/// A commit goes through `onGroupedEdit` (`performGroupedEdit`), so a rename
/// is its own undo step even when the mouse-down that ended it edits too — a
/// track's M, say — instead of sharing that event's implicit group (#69).
///
/// Whatever else was being typed into — that header field, a timecode —
/// commits BEFORE the name is read, so the field opens on the name that
/// commit produced (the shared editor blurs too, for the responder handoff).
///
/// The second half of the file is the following-the-layout mechanism for
/// ALL THREE renames: `relocateRename` and the track's and the marker's
/// frames and relocators, which the frozen file's `renameTrack` and
/// `renameMarker` hand to `beginRename` exactly as `beginClipRename` does.
extension TimelineView {

    // MARK: - Following the layout

    /// After a layout rebuild the open field follows its target; when the
    /// target is gone it is ended with its commit DROPPED, so a delete under
    /// an open field never sends a rename to a dead id. Called at the end of
    /// the frozen file's `rebuildLayout`, after the new layout and the
    /// content frame are in place.
    func relocateRename() {
        guard let field = renameField else { return }
        guard let frame = renameRelocate?() else {
            renameCommit = nil
            endRename()
            return
        }
        if field.frame != frame { field.frame = frame }
    }

    /// Escape: the field closes and keeps the old name, with no undo step. The
    /// commit is dropped BEFORE `endRename`, because removing the field fires
    /// `controlTextDidEndEditing`, which reads it — `relocateRename`'s path.
    @objc func control(
        _ control: NSControl, textView: NSTextView, doCommandBy commandSelector: Selector
    ) -> Bool {
        guard control === renameField,
              commandSelector == #selector(NSResponder.cancelOperation(_:))
        else { return false }
        renameCommit = nil
        endRename()
        return true
    }

    /// The track header's field: 20 pt over the row's 13 pt name label.
    func trackRenameFrame(row: Int) -> NSRect {
        NSRect(
            x: 6, y: layout.rowTop(row) - TimelineLayout.rulerHeight + 3,
            width: TimelineLayout.headerWidth - 12, height: 20)
    }

    func trackRenameRelocator(_ track: UInt32) -> () -> NSRect? {
        { [weak self] in
            guard let self, let index = self.snapshot.trackIndex(of: track) else { return nil }
            return self.trackRenameFrame(row: self.layout.row(forTrackIndex: index))
        }
    }

    /// The marker's field in the ruler, 40 pt left of its flag and never past
    /// the ruler's left edge.
    func markerRenameFrame(_ marker: MarkerSnapshot) -> NSRect {
        NSRect(x: max(layout.x(for: marker.time) - 40, 0), y: 3, width: 110, height: 20)
    }

    func markerRenameRelocator(_ marker: UInt32) -> () -> NSRect? {
        { [weak self] in
            guard let self, let now = self.snapshot.marker(marker) else { return nil }
            return self.markerRenameFrame(now)
        }
    }

    // MARK: - The clip's field

    /// The field is never narrower than this: a clip two frames long is a
    /// 2 pt bar at a low zoom, and a 2 pt field cannot be typed into.
    private static var renameMinWidth: CGFloat { 120 }

    /// The strip's 16 pt plus 2: a bezeled `NSTextField` needs a point above
    /// and below an 11 pt line, the same reason the track field is 20 pt
    /// over a 13 pt label. The extra 2 pt lie over the filmstrip's top edge,
    /// which is under the field either way.
    private static var renameHeight: CGFloat { DS.clipHeaderHeight + 2 }

    /// The field's rect over `id`'s name strip under the current layout, or
    /// nil when the clip is gone.
    ///
    /// Clamped to the visible lanes — from the header column's right edge
    /// (the column paints OVER the content's left edge) to the viewport's —
    /// because AppKit does not scroll a timeline to a field editor's caret:
    /// a double-click on the visible part of a long clip whose start is
    /// scrolled off would otherwise open a field whose left-aligned text and
    /// caret are thousands of points away, and the user would type blind
    /// into a bezel. A zoom's relocation reads the viewport BEFORE `setZoom`
    /// re-scrolls, so a clip pushed out of view by the zoom can leave its
    /// field at the old edge; the clip still visible after it, which is the
    /// case, is placed exactly.
    func clipRenameFrame(_ id: UInt32) -> CGRect? {
        guard let clip = snapshot.clip(id), let index = snapshot.trackIndex(of: clip.track)
        else { return nil }
        let row = layout.row(forTrackIndex: index)
        let body = TimelineContentView.bodyRect(layout.clipRect(clip, row: row))
        let visibleMinX = pinnedX + TimelineLayout.headerWidth
        let visibleMaxX = pinnedX + layout.viewport.width
        let x = max(body.minX, visibleMinX)
        let width = max(Self.renameMinWidth, min(body.maxX, visibleMaxX) - x)
        return CGRect(x: x, y: body.minY, width: width, height: Self.renameHeight)
    }

    /// Opens the field over `id`'s name strip.
    ///
    /// A clip on a locked track can still be renamed: a lock protects
    /// placement, a name is not placement, and the core's `set_clip`
    /// consults no lock — refusing here would invent a rule the op does not
    /// have.
    func beginClipRename(_ id: UInt32) {
        // Another editor's commit first (the module doc), so the name read
        // below is the one it produced.
        _ = window?.makeFirstResponder(nil)
        guard let clip = snapshot.clip(id), let frame = clipRenameFrame(id) else { return }
        let relocate: () -> NSRect? = { [weak self] in self?.clipRenameFrame(id) }
        beginRename(in: content, frame: frame, text: snapshot.name(of: clip), relocate: relocate) {
            [weak self] name in
            self?.onGroupedEdit?(
                "Rename Clip", [.setClip(clips: [id], patch: ClipPatch(name: .some(name)))])
        }
    }

    /// Clip ▸ Rename…: the field over the first selected clip in timeline
    /// order — the clip the Clip tab's header and the timeline bar's block
    /// speak for — scrolled into view first so it opens where the eye can
    /// find it. Nothing selected is a beep.
    func renameSelectedClip() {
        // Before the rect is read: a timecode field's commit can trim the clip.
        _ = window?.makeFirstResponder(nil)
        guard let clip = snapshot.clips.filter({ selection.contains($0.id) })
                .min(by: { $0.start < $1.start }),
              let index = snapshot.trackIndex(of: clip.track)
        else {
            NSSound.beep()
            return
        }
        var reveal = layout.clipRect(clip, row: layout.row(forTrackIndex: index))
        // Only the field's own width of a long clip, and grown by the two
        // floating bands: the header column and the ruler paint OVER the
        // content's left and top edges, so a rect that is merely inside the
        // clip view can still be under one of them.
        reveal.size.width = min(reveal.width, Self.renameMinWidth) + TimelineLayout.headerWidth
        reveal.origin.x -= TimelineLayout.headerWidth
        reveal.size.height += TimelineLayout.rulerHeight
        reveal.origin.y -= TimelineLayout.rulerHeight
        content.scrollToVisible(reveal)
        beginClipRename(clip.id)
    }
}
