    /// delete (spec §6).
    ///
    /// If that would empty the stack, the back-most track survives: it is
    /// the one a fresh project starts with, and keeping the bottom of the
    /// stack means the surviving track is where a drop lands.
    pub fn remove_empty_tracks(&self) -> Result<Outcome, String> {
        let mut next = self.clone();
        next.tracks
            .retain(|t| self.clips.iter().any(|c| c.track == t.id));
        if next.tracks.is_empty() {
            next.tracks = self.tracks.iter().take(1).cloned().collect();
        }
        self.finish(next)
    }

    // ---- markers ---------------------------------------------------------

    /// Adds a marker at `at`, snapped to the frame grid and clamped to 0 —
    /// a drag can start left of the timeline, and there is no negative time
    /// (spec §6).
    ///
    /// The default name is `Marker <count + 1>` and the default colour is
    /// `"red"`. `Err` when another marker already holds the tick: two
    /// markers may not share a time, and moving the existing one is the
    /// caller's decision, not this op's.
    pub fn add_marker(
        &self,
        at: Ticks,
        name: Option<&str>,
        chapter: Option<bool>,
        color: Option<&str>,
    ) -> Result<Outcome, String> {
        let at = self.snapped(at).max(0);
        if let Some(existing) = self.markers.iter().find(|m| m.time == at) {
            return Err(format!("marker {} is already at {at} ticks", existing.id));
        }

        let mut next = self.clone();
        let id = next.allocate_id();
        let name = name
            .map(|given| given.trim().to_string())
            .unwrap_or_else(|| format!("Marker {}", next.markers.len().saturating_add(1)));
        let color = color
            .map(str::trim)
            .filter(|given| !given.is_empty())
            .unwrap_or(DEFAULT_MARKER_COLOR)
            .to_string();
        next.markers.push(Marker {
            id,
            time: at,
            name,
            color,
            chapter: chapter.unwrap_or(false),
        });
        self.finish(next)
    }

    /// Sets any subset of a marker's fields; an omitted argument keeps its
///
/// Nested tracks and clips count toward the same two caps as the
/// timeline's. They are the same tracks and clips — a nest is a group held
/// in the parent's one id space, and flattening one at evaluation time
/// gives its clips real composition tracks — so counting them separately
/// would let a project with 64 nests of 64 tracks past a cap that exists to
/// bound exactly that.
pub fn check_caps(p: &Project) -> Result<(), String> {
    let nested_clips: usize = p.nests.iter().map(|n| n.clips.len()).sum();
    let nested_tracks: usize = p.nests.iter().map(|n| n.tracks.len()).sum();
    let clips = p.clips.len().saturating_add(nested_clips);
    let tracks = p.tracks.len().saturating_add(nested_tracks);
    if clips > MAX_CLIPS {
        return Err(format!("too many clips: {clips} (max {MAX_CLIPS})"));
    }
    if tracks > MAX_TRACKS {
        return Err(format!("too many tracks: {tracks} (max {MAX_TRACKS})"));
    }
    if p.markers.len() > MAX_MARKERS {
        return Err(format!(
            "too many markers: {} (max {})",
            p.markers.len(),
            MAX_MARKERS
        ));
    }
    if p.media.len() > MAX_MEDIA {
        return Err(format!(
            "too many media: {} (max {})",
            p.media.len(),
            MAX_MEDIA
        ));
    }
    Ok(())
}

/// Version 1 → 2. One key needs rewriting: a nest clip's `project`.
    /// caps, and saturating cannot silently reissue id 0.
    pub fn allocate_id(&mut self) -> u32 {
        let id = self.next_id;
