        let lane = Self.actionLane(
            content: Self.contentRect(rect), sizeIndex: owner.trackHeightIndex)
        guard lane.height > 0, lane.contains(point) else { return nil }
        return ActionBands.ordered(clip).last { action in
            action.duration > 0
